namespace recovered_stats_critical_threat{namespace{U equipment(U self,U mask,Ports&p){return p.equipment(p.read(p.read(self+0x24)+0xa2c),mask);}}U threat(U self,U offhand,Ports&p){U item=equipment(self,16,p);if(offhand&&item&&p.byte(p.rule(p.read(item+12))+8)!=3)item=equipment(self,32,p);if(!item)item=equipment(self,8,p);U base=1,bonus=0;if(item){base=p.byte(p.rule(p.read(item+12))+0x1e);if(p.property(item,0x1c,0))bonus=base;}U combat=p.read(p.read(self+0x24)+0x9c8);U attack=p.attack(combat,p.byte(combat+0x96c));U kind=p.half(attack+0x64);bonus+=base;switch(kind){case 8:case 31:bonus+=base;break;case 19:case 20:bonus+=base*2;break;case 77:case 81:bonus+=base*3;break;default:break;}return 21-bonus;}}
